import * as THREE from './vendor/three.module.js';
export function createBuilder(categories){
 const root=new THREE.Group(),parts=[],byId=new Map();
 const colors={shell:[0x475b64,.8,.32],dark:[0x182830,.5,.4],rubber:[0x151c21,.02,.88],metal:[0xaab8be,.85,.3],copper:[0xc68a5a,.8,.32],gold:[0xdac37e,.8,.28],pcb:[0x19654e,.24,.48],chip:[0x202d36,.35,.53],ceramic:[0xb5b6ae,.12,.55],sensor:[0x7472b8,.65,.25],flex:[0xc98835,.45,.45],thermal:[0x9cbdc1,.1,.9],red:[0xc76a5c,.3,.4]};
 const mat=k=>k==='glass'?new THREE.MeshPhysicalMaterial({color:0x5d8f9f,metalness:.2,roughness:.1,transparent:true,opacity:.32,side:THREE.DoubleSide,depthWrite:false,clearcoat:1}):new THREE.MeshStandardMaterial({color:colors[k]?.[0]??0x778b91,metalness:colors[k]?.[1]??.4,roughness:colors[k]?.[2]??.45});
 function rounded(w,h,r=.12){r=Math.min(r,w/3,h/3);const s=new THREE.Shape(),x=-w/2,y=-h/2;s.moveTo(x+r,y);s.lineTo(x+w-r,y);s.quadraticCurveTo(x+w,y,x+w,y+r);s.lineTo(x+w,y+h-r);s.quadraticCurveTo(x+w,y+h,x+w-r,y+h);s.lineTo(x+r,y+h);s.quadraticCurveTo(x,y+h,x,y+h-r);s.lineTo(x,y+r);s.quadraticCurveTo(x,y,x+r,y);return s;}
 function plate(w,h,d,r=.12,holes=[]){const s=rounded(w,h,r);for(const a of holes){let p;if(a.type==='circle'){p=new THREE.Path();p.absarc(a.x||0,a.y||0,a.r,0,Math.PI*2,true);}else{p=rounded(a.w,a.h,a.r||.08);if(a.x||a.y)p=new THREE.Path(p.getPoints(18).map(v=>new THREE.Vector2(v.x+(a.x||0),v.y+(a.y||0))));}s.holes.push(p);}const g=new THREE.ExtrudeGeometry(s,{depth:d,bevelEnabled:false,curveSegments:8});g.translate(0,0,-d/2);return g;}
 function ring(ro,ri,d){const s=new THREE.Shape();s.absarc(0,0,ro,0,Math.PI*2,false);const p=new THREE.Path();p.absarc(0,0,ri,0,Math.PI*2,true);s.holes.push(p);const g=new THREE.ExtrudeGeometry(s,{depth:d,bevelEnabled:false,curveSegments:24});g.translate(0,0,-d/2);return g;}
 function disk(r,d){const g=new THREE.CylinderGeometry(r,r,d,32);g.rotateX(Math.PI/2);return g;}
 function add(cat,name,en,geo,material,home,detail=[0,0,0],extra={}){const c=categories.find(c=>c.id===cat);if(!c)throw Error('Unknown category: '+cat);const n=parts.filter(p=>p.cat===cat).length+1,id=String(categories.indexOf(c)+1).padStart(2,'0')+'-'+String(n).padStart(2,'0');const group=new THREE.Group(),mesh=new THREE.Mesh(geo,mat(material));group.add(mesh);group.position.fromArray(home);if(extra.rotation)group.rotation.fromArray(extra.rotation);root.add(group);if(material!=='glass'&&material!=='rubber'){const e=new THREE.LineSegments(new THREE.EdgesGeometry(geo,35),new THREE.LineBasicMaterial({color:0xa7cfc5,transparent:true,opacity:.25}));e.userData.edge=true;mesh.add(e);}const p={id,name,en,cat,group,mesh,home:new THREE.Vector3(...home),spread:new THREE.Vector3(...(extra.spread||c.offset)),detail:new THREE.Vector3(...detail),role:extra.role||'结构组成',desc:extra.desc||c.desc,material:extra.material||c.material,size:extra.size||'概念比例'};group.userData.partId=id;parts.push(p);byId.set(id,p);return p;}
 function box(cat,name,en,w,h,d,material,home,detail=[0,0,0],extra={}){return add(cat,name,en,plate(w,h,d,Math.min(.12,w*.12,h*.12)),material,home,detail,extra);}
 function child(p,geo,m,position=[0,0,0]){const mesh=new THREE.Mesh(geo,typeof m==='string'?mat(m):m);mesh.position.fromArray(position);p.group.add(mesh);return mesh;}
 function label(p,text,w,h,pos=[0,0,0],fg='#cde5db',bg='#24323a'){const c=document.createElement('canvas');c.width=512;c.height=256;const x=c.getContext('2d');x.fillStyle=bg;x.fillRect(0,0,512,256);x.textAlign='center';x.fillStyle=fg;x.font='bold 50px monospace';x.fillText(text,256,132,470);x.font='19px monospace';x.fillText('ENGINEERING CONCEPT',256,180);const t=new THREE.CanvasTexture(c);t.colorSpace=THREE.SRGBColorSpace;return child(p,new THREE.PlaneGeometry(w,h),new THREE.MeshStandardMaterial({map:t,metalness:.15,roughness:.6}),pos);}
 function screen(p,w,h,pos,flip=false){const c=document.createElement('canvas');c.width=768;c.height=1024;const x=c.getContext('2d'),g=x.createLinearGradient(0,0,768,1024);g.addColorStop(0,'#18363f');g.addColorStop(.5,'#65ad9c');g.addColorStop(1,'#14223f');x.fillStyle=g;x.fillRect(0,0,768,1024);for(let i=0;i<5;i++){x.strokeStyle=['#b6ffe160','#67d9ce70','#6e8ef070','#deefd660','#e5dca750'][i];x.lineWidth=70-i*7;x.beginPath();x.ellipse(380-i*45,670-i*90,420-i*43,300-i*28,-.8,0,Math.PI*2);x.stroke();}x.fillStyle='#e6fff3';x.font='100px monospace';x.textAlign='center';x.fillText('09:41',384,218);x.font='22px monospace';x.fillText('EXPLORE THE INSIDE',384,276);x.fillStyle='#dbfff080';x.fillRect(300,948,168,7);const tx=new THREE.CanvasTexture(c);tx.colorSpace=THREE.SRGBColorSpace;const m=child(p,new THREE.PlaneGeometry(w,h),new THREE.MeshBasicMaterial({map:tx,side:THREE.DoubleSide}),pos);if(flip)m.rotation.y=Math.PI;return m;}
 function circuit(p,w,h){for(let i=0;i<32;i++){const x=-w*.44+(i%8)*w*.12,y=-h*.43+Math.floor(i/8)*h*.24;const points=[new THREE.Vector3(x,y,.067),new THREE.Vector3(x+w*.04,y,.067),new THREE.Vector3(x+w*.08,y+h*.07,.067),new THREE.Vector3(x+w*.08,y+h*.17,.067)];p.group.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(points),new THREE.LineBasicMaterial({color:i%5?0x73a382:0xe6c776,transparent:true,opacity:.6})));}for(let i=0;i<20;i++)child(p,disk(.035,.01),'gold',[-w*.43+(i%10)*w*.095,(i<10?-1:1)*h*.46,.064]);}
 function passives(cat,origin,columns=8,rows=4,spacing=.34){for(let i=0;i<columns*rows;i++){const p=box(cat,`${i%2?'贴片电阻 R':'去耦电容 C'}${String(i+1).padStart(2,'0')}`,i%2?'SMD resistor':'Decoupling capacitor',.16,.09,.07,i%2?'dark':'ceramic',[origin[0]+i%columns*spacing,origin[1]+Math.floor(i/columns)*spacing,origin[2]],[0,.04,.4+(i%3)*.2],{role:i%2?'信号调理':'电源滤波',material:i%2?'厚膜电阻 / 陶瓷':'陶瓷 / 金属端电极'});for(const s of [-1,1])child(p,new THREE.BoxGeometry(.03,.092,.075),'metal',[s*.068,0,0]);}}
 function screw(cat,name,position,detail=[0,0,0],extra={}){const p=add(cat,name,'Fixing screw',disk(.09,.055),'metal',position,detail,{role:'机械固定',material:'不锈钢（示意）',...extra});child(p,disk(.043,.24),'metal',[0,0,-.14]);const dark=new THREE.MeshBasicMaterial({color:0x152329});child(p,new THREE.BoxGeometry(.1,.02,.006),dark,[0,0,.031]);child(p,new THREE.BoxGeometry(.02,.1,.006),dark,[0,0,.031]);return p;}
 function fan(cat,name,position,radius,detail,extra={}){const p=add(cat,name,'Cooling fan rotor',disk(radius*.25,.12),'dark',position,detail,{role:'气流驱动',...extra});child(p,ring(radius,radius*.94,.13),'dark');for(let i=0;i<16;i++){const a=i*Math.PI/8;const blade=child(p,new THREE.BoxGeometry(radius*.68,radius*.11,.06),'dark',[Math.cos(a)*radius*.57,Math.sin(a)*radius*.57,0]);blade.rotation.z=a+.35;}return p;}
 function finish(){for(const p of parts)p.group.traverse(o=>{if(o.material)o.userData.base={color:o.material.color?.clone(),emissive:o.material.emissive?.clone(),emissiveIntensity:o.material.emissiveIntensity,opacity:o.material.opacity,transparent:o.material.transparent,depthWrite:o.material.depthWrite};});return {root,parts,byId};}
 return {root,parts,byId,box,add,child,plate,ring,disk,label,screen,circuit,passives,screw,fan,finish};
}
